    // [WSCoop] The split dialog's answer (see WSQoLExtras).
    void WSGrabAmount(UItemStack ItemStack, int Amount)
    {
        if (!IsValid(ItemStack) || Amount <= 0 || HUD.GetGrabbedItem() != nullptr)
            return;
        if (Amount >= ItemStack.GetStackSize())
        {
            HUD.SetGrabbedItem(ItemStack);
            PlayerInventoryComp.GrabItemStack(ItemStack);
            return;
